# 使用脚本自动化部署
#!/bin/bash
deploy.sh --env=production --app=web-api

# ========== Terraform基础设施即代码 ==========
# main.tf
terraform {
  required_providers {
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.0"
    }
  }
}

provider "kubernetes" {
  config_path = "~/.kube/config"
}

# EKS集群创建
resource "aws_eks_cluster" "main" {
  name     = "production-cluster"
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids = aws_subnet.private[*].id
  }

  # 启用集群日志
  enabled_cluster_log_types = ["api", "audit", "authenticator"]
}

# 节点组管理
resource "aws_eks_node_group" "general" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "general-workers"
  node_role_arn   = aws_iam_role.node.arn

  scaling_config {
    desired_size = 3
    max_size     = 10
    min_size     = 2
  }

  instance_types = ["t3.medium"]
  capacity_type  = "ON_DEMAND"
}

# ========== Grafana仪表板配置 ==========
apiVersion: integreatly.org/v1alpha1
kind: GrafanaDashboard
metadata:
  name: sre-maturity-dashboard
  namespace: monitoring
spec:
  json: |
    {
      "dashboard": {
        "title": "SRE运维成熟度仪表板",
        "panels": [
          {
            "title": "总体成熟度评分",
            "type": "gauge",
            "targets": [
              {
                "expr": "sre_maturity_score",
                "legendFormat": "当前得分"
              }
            ],
            "fieldConfig": {
              "defaults": {
                "min": 0,
                "max": 5,
                "thresholds": {
                  "mode": "absolute",
                  "steps": [
                    {"color": "red", "value": null},
                    {"color": "orange", "value": 1.5},
                    {"color": "yellow", "value": 2.5},
                    {"color": "blue", "value": 3.5},
                    {"color": "green", "value": 4.5}
                  ]
                }
              }
            }
          },
          {
            "title": "各维度成熟度对比",
            "type": "barchart",
            "targets": [
              {"expr": "sre_reliability_score", "legendFormat": "可靠性"},
              {"expr": "sre_automation_score", "legendFormat": "自动化"},
              {"expr": "sre_observability_score", "legendFormat": "可观测性"},
              {"expr": "sre_process_score", "legendFormat": "流程"},
              {"expr": "sre_people_score", "legendFormat": "人员"}
            ]
          },
          {
            "title": "成熟度趋势",
            "type": "graph",
            "targets": [
              {"expr": "sre_maturity_score[30d]", "legendFormat": "总体得分"}
            ]
          },
          {
            "title": "改进建议优先级",
            "type": "table",
            "targets": [
              {
                "expr": "sre_improvement_priorities",
                "format": "table"
              }
            ],
            "transformations": [
              {
                "id": "organize",
                "options": {
                  "renameByName": {
                    "area": "改进领域",
                    "priority": "优先级",
                    "effort": "投入 effort",
                    "impact": "预期影响"
                  }
                }
              }
            ]
          }
        ]
      }
    }

{
  "dashboard": {
    "title": "SRE SLO监控面板",
    "refreshInterval": "30s",
    "timezone": "browser",
    "panels": [
      {
        "type": "gauge",
        "title": "服务可用性",
        "datasource": "prometheus",
        "targets": [
          {
            "expr": "avg_over_time(up{job=\"api-server\"}[30d]) * 100",
            "legendFormat": "当前可用性"
          }
        ],
        "thresholds": [
          { "value": 99.9, "color": "green" },
          { "value": 99.5, "color": "yellow" },
          { "value": 99.0, "color": "red" }
        ]
      },
      {
        "type": "graph",
        "title": "错误预算消耗趋势",
        "targets": [
          {
            "expr": "increase(errors_total[1h]) / increase(requests_total[1h])",
            "legendFormat": "错误率"
          },
          {
            "expr": "0.001",  // 0.1% 错误预算阈值
            "legendFormat": "预算阈值"
          }
        ]
      },
      {
        "type": "stat",
        "title": "剩余错误预算",
        "targets": [
          {
            "expr": "1 - (sum(increase(errors_total[30d])) / sum(increase(requests_total[30d]))) / 0.001",
            "legendFormat": "预算余额"
          }
        ]
      }
    ]
  }
}
